select

from patient_origin po
where po.id = #{parentId}

SELECT
    pbi.id AS patientId,
    CASE
        WHEN pbi.origin_type=1 THEN '员工转介绍'
        WHEN pbi.origin_type=2 THEN '患者转介绍'
        WHEN pbi.origin_type=12 THEN '未知来源'
        ELSE po.name
    END AS tagName
FROM patient_base_info pbi
LEFT JOIN patient_origin po ON pbi.origin_id=po.id

    pbi.origin_id > 0


            AND (
                DATE_FORMAT(pbi.upd_time, '%Y-%m-%d') BETWEEN #{query.startDate} AND #{query.endDate}
                OR DATE_FORMAT(po.upd_time, '%Y-%m-%d') BETWEEN #{query.startDate} AND #{query.endDate}
            )




            AND (
                DATE_FORMAT(pbi.upd_time, '%Y-%m') BETWEEN #{query.startDate} AND #{query.endDate}
                OR DATE_FORMAT(po.upd_time, '%Y-%m') BETWEEN #{query.startDate} AND #{query.endDate}
            )




            AND (
                DATE_FORMAT(pbi.upd_time, '%Y') BETWEEN #{query.startDate} AND #{query.endDate}
                OR DATE_FORMAT(po.upd_time, '%Y') BETWEEN #{query.startDate} AND #{query.endDate}
            )
